     1→use anyhow::{Context, Result, bail};
     2→use std::fs;
     3→use std::io::Write;
     4→use std::path::Path;
     5→use std::process::Command;
     6→
     7→use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
     8→use crate::tspec::load_spec;
     9→use crate::types::{CargoParam, LinkerParam, Profile, RustcParam, Spec};
    10→
    11→/// Build a crate with a spec
    12→pub fn build_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<()> {
    13→    let workspace = find_workspace_root()?;
    14→    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    15→    let tspec_path = find_tspec(&crate_dir, tspec)?;
    16→
    17→    // Track if we generated a build.rs
    18→    let build_rs_path = crate_dir.join("build.rs");
    19→    let had_build_rs = build_rs_path.exists();
    20→
    21→    // Apply spec if present, otherwise plain cargo build
    22→    let status = if let Some(path) = &tspec_path {
    23→        let spec = load_spec(path)?;
    24→        println!("Building {} with spec {}", crate_name, path.display());
    25→
    26→        // Generate temporary build.rs for linker flags if needed
    27→        let has_linker_args = spec
    28→            .linker
    29→            .iter()
    30→            .any(|p| matches!(p, LinkerParam::Args(_)));
    31→        if has_linker_args && !had_build_rs {
    32→            generate_build_rs(&build_rs_path, crate_name, &spec)?;
    33→        }
    34→
    35→        let mut cmd = build_cargo_command(&spec, &workspace)?;
    36→        cmd.arg("build");
    37→        cmd.arg("-p").arg(crate_name);
    38→        cmd.current_dir(&workspace);
    39→
    40→        apply_spec_to_command(&mut cmd, &spec, &workspace, release)?;
    41→        cmd.status().context("failed to run cargo")?
    42→    } else {
    43→        println!("Building {} (no tspec)", crate_name);
    44→        let mut cmd = Command::new("cargo");
    45→        cmd.arg("build");
    46→        cmd.arg("-p").arg(crate_name);
    47→        cmd.current_dir(&workspace);
    48→        if release {
    49→            cmd.arg("--release");
    50→        }
    51→        cmd.status().context("failed to run cargo")?
    52→    };
    53→
    54→    // Clean up generated build.rs (only if we created it)
    55→    if !had_build_rs && build_rs_path.exists() {
    56→        let _ = fs::remove_file(&build_rs_path);
    57→    }
    58→
    59→    if !status.success() {
    60→        bail!("cargo build failed");
    61→    }
    62→
    63→    Ok(())
    64→}
    65→
    66→/// Generate a temporary build.rs with scoped linker flags from tspec.toml
    67→pub fn generate_build_rs(path: &Path, crate_name: &str, spec: &Spec) -> Result<()> {
    68→    let mut lines = vec![
    69→        "// Generated by xt - do not edit".to_string(),
    70→        "fn main() {".to_string(),
    71→    ];
    72→
    73→    for param in &spec.linker {
    74→        if let LinkerParam::Args(args) = param {
    75→            for arg in args {
    76→                lines.push(format!(
    77→                    "    println!(\"cargo:rustc-link-arg-bin={}={}\");",
    78→                    crate_name, arg
    79→                ));
    80→            }
    81→        }
    82→    }
    83→
    84→    lines.push("}".to_string());
    85→    fs::write(path, lines.join("\n")).context("failed to write build.rs")?;
    86→    Ok(())
    87→}
    88→
    89→/// Check if spec requires nightly toolchain
    90→fn requires_nightly(spec: &Spec) -> bool {
    91→    // BuildStd requires nightly
    92→    let has_build_std = spec
    93→        .rustc
    94→        .iter()
    95→        .any(|p| matches!(p, RustcParam::BuildStd(_)));
    96→
    97→    // Unstable cargo flags require nightly
    98→    let has_unstable = spec
    99→        .cargo
   100→        .iter()
   101→        .any(|p| matches!(p, CargoParam::Unstable(_)));
   102→
   103→    has_build_std || has_unstable
   104→}
   105→
   106→/// Build the base cargo command (with toolchain if needed)
   107→fn build_cargo_command(spec: &Spec, _workspace: &Path) -> Result<Command> {
   108→    let mut cmd = Command::new("cargo");
   109→
   110→    if requires_nightly(spec) {
   111→        cmd.arg("+nightly");
   112→    }
   113→
   114→    Ok(cmd)
   115→}
   116→
   117→/// Apply spec parameters to a cargo command
   118→pub fn apply_spec_to_command(
   119→    cmd: &mut Command,
   120→    spec: &Spec,
   121→    workspace: &Path,
   122→    release: bool,
   123→) -> Result<()> {
   124→    // Handle cargo params
   125→    let mut has_profile = false;
   126→    for param in &spec.cargo {
   127→        match param {
   128→            CargoParam::Profile(p) => {
   129→                has_profile = true;
   130→                match p {
   131→                    Profile::Release => {
   132→                        cmd.arg("--release");
   133→                    }
   134→                    Profile::Debug => {
   135→                        // Debug is default, no flag needed
   136→                    }
   137→                }
   138→            }
   139→            CargoParam::TargetTriple(triple) => {
   140→                cmd.arg("--target").arg(triple);
   141→            }
   142→            CargoParam::TargetJson(path) => {
   143→                cmd.arg("--target").arg(path);
   144→            }
   145→            CargoParam::Unstable(flag) => {
   146→                cmd.arg("-Z").arg(flag);
   147→            }
   148→        }
   149→    }
   150→
   151→    // If no profile in spec but release flag passed, use release
   152→    if !has_profile && release {
   153→        cmd.arg("--release");
   154→    }
   155→
   156→    // Collect rustc flags
   157→    let mut rustc_flags: Vec<String> = Vec::new();
   158→
   159→    // Handle rustc params
   160→    for param in &spec.rustc {
   161→        match param {
   162→            RustcParam::OptLevel(level) => {
   163→                let lvl = match level {
   164→                    crate::types::OptLevel::O0 => "0",
   165→                    crate::types::OptLevel::O1 => "1",
   166→                    crate::types::OptLevel::O2 => "2",
   167→                    crate::types::OptLevel::O3 => "3",
   168→                    crate::types::OptLevel::Os => "s",
   169→                    crate::types::OptLevel::Oz => "z",
   170→                };
   171→                rustc_flags.push(format!("-C opt-level={}", lvl));
   172→            }
   173→            RustcParam::Panic(strategy) => {
   174→                let s = match strategy {
   175→                    crate::types::PanicStrategy::Abort => "abort",
   176→                    crate::types::PanicStrategy::Unwind => "unwind",
   177→                    crate::types::PanicStrategy::ImmediateAbort => "immediate-abort",
   178→                };
