        cmd.status().context("failed to run cargo")?
    } else {
        println!("Building {} (no tspec)", crate_name);
        let mut cmd = Command::new("cargo");
        cmd.arg("build");
        cmd.arg("-p").arg(crate_name);
        cmd.current_dir(&workspace);
        if release {
            cmd.arg("--release");
        }
        cmd.status().context("failed to run cargo")?
    };

    // Clean up generated build.rs (only if we created it)
    if !had_build_rs && build_rs_path.exists() {
        let _ = fs::remove_file(&build_rs_path);
    }

    if !status.success() {
        bail!("cargo build failed");
    }

    println!("  {}", binary_path.display());
    Ok(BuildResult { binary_path })
}

/// Get binary path for a build with a spec
fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
    let is_release = release
        || spec
            .cargo
            .iter()
            .any(|p| matches!(p, CargoParam::Profile(Profile::Release)));

    let target = spec.cargo.iter().find_map(|p| match p {
        CargoParam::TargetTriple(t) => Some(t.clone()),
        CargoParam::TargetJson(p) => p.file_stem().map(|s| s.to_string_lossy().to_string()),
        _ => None,
    });

    let profile_dir = if is_release { "release" } else { "debug" };

    match target {
        Some(t) => workspace
            .join("target")
            .join(t)
            .join(profile_dir)
            .join(crate_name),
        None => workspace.join("target").join(profile_dir).join(crate_name),
    }
}

/// Get binary path for a simple build (no spec)
fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
    let profile_dir = if release { "release" } else { "debug" };
    workspace.join("target").join(profile_dir).join(crate_name)
}

/// Strip symbols from a binary
pub fn strip_binary(path: &Path) -> Result<()> {
    if !path.exists() {
        bail!("binary not found: {}", path.display());
    }

    let status = Command::new("strip")
        .arg(path)
        .status()
        .context("failed to run strip")?;

    if !status.success() {
        bail!("strip failed");
    }

    // Report new size
    if let Ok(meta) = fs::metadata(path) {
