use anyhow::{Context, Result};
use std::process::Command;

use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root, get_binary_path, get_binary_path_simple};
use crate::tspec::load_spec;

/// Build and run a crate with a spec, returns the exit code
pub fn run_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<i32> {
    let workspace = find_workspace_root()?;
    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    let tspec_path = find_tspec(&crate_dir, tspec)?;

    // Determine binary path
    let binary_path = if let Some(path) = &tspec_path {
        let spec = load_spec(path)?;
        get_binary_path(&workspace, crate_name, &spec, release)
    } else {
        get_binary_path_simple(&workspace, crate_name, release)
    };

    // Build first
    crate::build::build_crate(crate_name, tspec, release)?;

    // Run binary
    println!("Running {}", binary_path.display());
    let status = Command::new(&binary_path)
        .status()
        .with_context(|| format!("failed to run {}", binary_path.display()))?;

    Ok(status.code().unwrap_or(1))
}

